// Interface : un contrat, aucune implémentation
interface Notifier {
    void send(String to, String message);
}

// Classe abstraite : du code partagé + un trou à remplir
abstract class RetryingNotifier implements Notifier {
    public void send(String to, String message) {
        for (int attempt = 1; attempt <= 3; attempt++) {
            if (tryOnce(to, message)) return; // logique commune : réessais
        }
        throw new IllegalStateException("échec après 3 essais");
    }
    protected abstract boolean tryOnce(String to, String message); // à définir
}

// Classe concrète : instanciable, remplit le trou
class EmailNotifier extends RetryingNotifier {
    protected boolean tryOnce(String to, String message) { /* envoi SMTP */ return true; }
}

classDiagram
    class Notifier {
        <<interface>>
        +send()
    }
    class RetryingNotifier {
        <<abstract>>
        +send()
        #tryOnce()*
    }
    class EmailNotifier {
        #tryOnce()
    }
    class SmsNotifier {
        #tryOnce()
    }
    Notifier <|.. RetryingNotifier : implements
    RetryingNotifier <|-- EmailNotifier : extends
    RetryingNotifier <|-- SmsNotifier : extends

// src PRODUIT des T (on lit) -> extends ; dest CONSOMME des T (on écrit) -> super
static <T> void copy(List<? extends T> src, List<? super T> dest) {
    for (T item : src) {   // lecture OK depuis un producteur
        dest.add(item);    // écriture OK dans un consommateur
    }
}

List<Integer> ints   = List.of(1, 2, 3);
List<Number>  nums   = new ArrayList<>();
copy(ints, nums);      // ✅ Integer produit, écrit dans une liste de Number

// Producteur : on lit, on n'écrit pas
double sum(List<? extends Number> xs) {
    double s = 0; for (Number n : xs) s += n.doubleValue();
    // xs.add(1);  // ❌ refusé : type exact inconnu, écriture interdite
    return s;
}
sum(ints);             // ✅ accepte List<Integer> grâce à ? extends

sealed interface Expr permits Num, Add, Mul {}
record Num(double v) implements Expr {}
record Add(Expr left, Expr right) implements Expr {}
record Mul(Expr left, Expr right) implements Expr {}

// switch exhaustif + déconstruction imbriquée : pas de default, le compilateur vérifie
static double eval(Expr e) {
    return switch (e) {
        case Num(double v)        -> v;
        case Add(Expr l, Expr r)  -> eval(l) + eval(r);
        case Mul(Expr l, Expr r)  -> eval(l) * eval(r);
    };
}
